#!/usr/bin/env bash
# Documentation : partie « API » (tRPC) en dix chapitres, profondeur du tutoriel d'origine restaurée ;
# service assertDisciplineReferences, getAllPublished retiré, auth.router sur ctx.prisma.
# Prérequis : apply-fix-trpc-gardes.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-api-trpc.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/api/pourquoi-trpc.mdx" 2>/dev/null | grep -qF "Quand la donnée change de nature"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "errorFormatter" "packages/backend/src/trpc/core.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-trpc-gardes.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/auth/authentification.mdx" "apps/web/src/features/admin/disciplines/components/DisciplinesTable.tsx" "packages/backend/src/modules/auth/router.ts" "packages/backend/src/modules/disciplines/router.ts")
EXPECT=("4cbf4b0a2841:apps/web/content/docs/dev/auth/authentification.mdx" "c84fca1621db:apps/web/src/features/admin/disciplines/components/DisciplinesTable.tsx" "d70490e299c5:packages/backend/src/modules/auth/router.ts" "c86690f9f714:packages/backend/src/modules/disciplines/router.ts")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/dev/api/contexte-et-intention.mdx" "apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "apps/web/content/docs/dev/api/la-carte-du-systeme.mdx" "apps/web/content/docs/dev/api/le-circuit-complet.mdx" "apps/web/content/docs/dev/api/le-routeur-metier.mdx" "apps/web/content/docs/dev/api/maitriser-la-sortie.mdx" "apps/web/content/docs/dev/api/pourquoi-trpc.mdx" "apps/web/content/docs/dev/api/proteger-une-procedure.mdx" "apps/web/content/docs/dev/api/valider-l-entree.mdx" "packages/backend/src/modules/disciplines/services/assertDisciplineReferences.service.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "packages/backend/src/modules/disciplines/services" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "Quand la donnée change de nature" "apps/web/content/docs/dev/api/pourquoi-trpc.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/api"
base64 -d > "apps/web/content/docs/dev/api/contexte-et-intention.mdx" <<'B64'
