trap - ERR

# Table de l'index : ligne « API », quel que soit son texte actuel.
F=apps/web/content/docs/dev/index.mdx
if ! git diff --quiet HEAD -- "$F"; then echo "❌ $F a des modifications non commitées"; restore; exit 1; fi
MODIFIED+=("$F")
python3 - "$F" <<'PY2'
import re, sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
new = '["API","tRPC, en dix chapitres : pourquoi tRPC, la carte du système, contexte et intention, le routeur métier et ses services, fabriquer une procédure, la protéger, valider l’entrée, gérer les erreurs, maîtriser la sortie, le circuit complet.","rédigée"]'
s2, n = re.subn(r'\["API","[^"]*","[^"]*"\]', lambda m: new, s)
assert n == 1, n
open(p, "w", encoding="utf-8").write(s2)
PY2
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
node scripts/build-procedure-map.mjs --write >/dev/null 2>&1 || { echo "❌ carte des procédures : échec"; restore; exit 1; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
OLDF=apps/web/content/docs/dev/api/trpc.mdx
if [ -e "$OLDF" ]; then git rm -q "$OLDF"; fi
git add "${MODIFIED[@]}" "${CREATED[@]}" apps/web/src/features/docs/entities/procedureMap.generated.json
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
docs: partie « API » (tRPC) en 10 chapitres — profondeur du tutoriel d'origine restaurée

Le tutoriel trpc_backend (3 113 lignes) est restauré en entier, découpé en dix chapitres (api/),
le code des extraits pris dans le projet actuel, les acquis du chapitre « L'API avec tRPC » fondus
dedans (brouillons, superjson, deux clients, invalidation). Les parties RBAC (rôles, permissions)
sont réécrites sur le modèle réel : groupe Administrateurs, gardes d'espace, règles métier.
- disciplines : assertDisciplineReferences (vérifications partagées par create et update) ;
  getAllPublished retiré (doublon inutilisé de getAllForMenu)
- auth : ctx.prisma au lieu de l'import global ; commentaire de tête en français
- api/trpc.mdx remplacé ; index et authentification mis à jour

